        "uSaKHqyDykW3HaFh": {
          "name": "Cura do Vazio",
          "description": ""
        },
        "snTIGb2g7DF1L8wx": {
          "name": "Golpe Fantasma",
          "description": "Cada inimigo no espaço do enxame de paralelepípedos sofre 1d6 de dano de concussão] (verificação (reflexo, dc:17, básico))."
        },
        "LpV8movSEB2EyosK": {
          "name": "Limite de liquidação",
          "description": "Um enxame típico de paralelepípedos deve permanecer no assentamento onde se originou e não pode viajar mais do que 1 milha dele sem se desintegrar em pedaços componentes, revivendo se seus pedaços forem devolvidos a esta área. Ocasionalmente, enxames de paralelepípedos estão vinculados a um edifício, estrada ou distrito específico, em vez de a um assentamento."
        }
